import{_ as i,o as t,c as u,a2 as n}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Orodha ya Mapendekezo ya Mipangilio ya Upanuzi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/98-扩展设定建议清单.md","filePath":"sw/98-扩展设定建议清单.md","lastUpdated":1789183869000}'),o={name:"sw/98-扩展设定建议清单.md"};function k(e,a,d,m,w,l){return t(),u("div",null,[...a[0]||(a[0]=[n('<h1 id="orodha-ya-mapendekezo-ya-mipangilio-ya-upanuzi" tabindex="-1">Orodha ya Mapendekezo ya Mipangilio ya Upanuzi <a class="header-anchor" href="#orodha-ya-mapendekezo-ya-mipangilio-ya-upanuzi" aria-label="Permalink to &quot;Orodha ya Mapendekezo ya Mipangilio ya Upanuzi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>98</td></tr><tr><td>Moduli</td><td>Viambatanisho na Vifaa vya Rujia</td></tr><tr><td>Maneno muhimu</td><td>mipangilio ya upanuzi, mapendekezo ya ubunifu, mwelekeo wa mipangilio, ufunguzi, maeneo yaendelezayo</td></tr></tbody></table><h2 id="_1-maelezo" tabindex="-1">1. Maelezo <a class="header-anchor" href="#_1-maelezo" aria-label="Permalink to &quot;1. Maelezo&quot;">​</a></h2><p>Hati hii inaorodhesha mwelekeo na mapendekezo yanayopatikana kwa ubunifu wa upanuzi katika mfumo wa mipangilio wa Ustaarabu wa Usawa wa Nanga, lengo lake ni kutoa msukumo na mwongozo kwa wabunifu wa mipangilio, kuwasaidia kufanya upanuzi wa mipangilio wenye thamani katika mfumo uliopo. Orodha hii imeainishwa kulingana na moduli, na kila mwelekeo wa upanuzi una maelezo ya mwelekeo, thamani ya upanuzi, uhusiano na mipangilio iliyopo, na mapendekezo ya ubunifu. Inahitajika kusisitiza kwamba orodha hii ni rujia tu ya mapendekezo; wabunifu wanaweza kufanya kazi kwa uhuru kwa masharti ya kufuata utendekanaji wa mipangilio, au wanaweza kukuza mwelekeo mpya kabisa ambao haujajumuishwa katika orodha hii. Mipangilio yote ya upanuzi lazima ipite katika ukaguzi wa Hati 97 &quot;Jedwali la Kujikagua Utofauti wa Mipangilio&quot; kabla ya kuingizwa rasmi.</p><h2 id="_2-mwelekeo-wa-upanuzi-wa-mtazamo-wa-dunia-na-mipangilio-ya-msingi" tabindex="-1">2. Mwelekeo wa Upanuzi wa Mtazamo wa Dunia na Mipangilio ya Msingi <a class="header-anchor" href="#_2-mwelekeo-wa-upanuzi-wa-mtazamo-wa-dunia-na-mipangilio-ya-msingi" aria-label="Permalink to &quot;2. Mwelekeo wa Upanuzi wa Mtazamo wa Dunia na Mipangilio ya Msingi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Mwelekeo wa Upanuzi</th><th>Thamani ya Upanuzi</th><th>Mipangilio Inayohusiana</th><th>Pendekezo la Ubunifu</th></tr></thead><tbody><tr><td>E01</td><td>Uwepo wa nje ya mipaka ya ulimwengu</td><td>Kuchunguza ikiwa kuna ulimwengu mwingine au uwepo wa mwelekeo wa juu zaidi nje ya mtandao wa sheria za Hengyuanzhou, kutoa mtazamo wa ulimwengu mkubwa zaidi kwa mipangilio</td><td>Hati 00, Hati 28</td><td>Inaweza kusanidi uwepo wa &quot;ukuta wa ulimwengu&quot; na hadithi za changamoto chache za wachunguzi walivunja ukuta wa ulimwengu, kuacha alama za mwingiliano kati ya ulimwengu katika siku zijazo</td></tr><tr><td>E02</td><td>Kiini cha mapenzi ya ulimwengu</td><td>Kujadili kwa kina ikiwa kuna &quot;mapenzi ya ulimwengu&quot; yoyote katika safu ya chini ya mtandao wa sheria na uhusiano wake na mchakato wa nanga</td><td>Hati 00, Hati 20</td><td>Inaweza kusanidi mapenzi ya ulimwengu kama tukio la kujitokeza kwa sheria kisicho na utu, badala ya mungu fulani, kudumisha msimamo wa &quot;kulingana na ukweli&quot;</td></tr><tr><td>E03</td><td>Ustaarabu uliopotea wa enzi ya kabla ya nanga</td><td>Kusanidi kwa kina ustaarabu ambao ulikuwa ustaarabu lakini umepotea katika enzi ya kabla ya nanga, kuimarisha kina cha kihistoria</td><td>Hati 71, Hati 93</td><td>Inaweza kusanidi ustaarabu 3-5 uliopotea unaowakilisha, kila ustaarabu na mfumo wake wa u cultivating, utamaduni, na sababu za kupotea, kutoa nyenzo kwa mipangilio ya kale</td></tr><tr><td>E04</td><td>Shule za falsafa za dhana ya usawa</td><td>Chini ya mfumo mkubwa wa &quot;kupinga ubaozi, kushauri usawa&quot;, kusanidi tafsiri tofauti za shule tofauti za falsafa kwa dhana ya usawa</td><td>Hati 04, Hati 03</td><td>Inaweza kusanidi shule kama vile &quot;shule ya usawa wa kizalendo&quot;, &quot;shule ya usawa wa wastani&quot;, &quot;shule ya usawa wa mazingira&quot;, &quot;shule ya usawa wa teknolojia&quot;, na mapigano ya mawazo kati yao yanaweza kuwa mvutano muhimu wa mzunguko wa hadithi</td></tr></tbody></table><h2 id="_3-mwelekeo-wa-upanuzi-wa-mfumo-wa-u-cultivating" tabindex="-1">3. Mwelekeo wa Upanuzi wa Mfumo wa U cultivating <a class="header-anchor" href="#_3-mwelekeo-wa-upanuzi-wa-mfumo-wa-u-cultivating" aria-label="Permalink to &quot;3. Mwelekeo wa Upanuzi wa Mfumo wa U cultivating&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Mwelekeo wa Upanuzi</th><th>Thamani ya Upanuzi</th><th>Mipangilio Inayohusiana</th><th>Pendekezo la Ubunifu</th></tr></thead><tbody><tr><td>E05</td><td>Njia za kina za mfumo mmoja</td><td>Kupanua kwa kina moja ya mifumo mia tatu, ikiwa ni pamoja na njia za u cultivating mahususi, njia za kupita kwa kina, makosa ya kawaida, n.k.</td><td>Hati 10-19, Hati 91</td><td>Inapendekezwa kipaumbele kupanua misingi mitatu ya asili na mifumo katika kategoria ya uhandisi wa matumizi inayounganishwa kwa karibu na teknolojia; hati ya kina ya kila mfumo inaweza kujumuisha hatua za u cultivating, fomula za akili, mahitaji ya rasilimali, onyo za hatari, n.k.</td></tr><tr><td>E06</td><td>Mipango ya mchanganyiko wa u cultivating wa pamoja wa mifumo</td><td>Kuchunguza uingiliano wa u cultivating wa pamoja kati ya mifumo tofauti na kuunda mipango bora ya mchanganyiko wa mifumo mingi</td><td>Hati 10, Hati 11-13</td><td>Inaweza kusanidi &quot;mchanganyiko wa dhahabu&quot; (kama vile kurudia tafakari + sheria za nafasi + uhandisi wa matumizi) na mchanganyiko anuwai wa nje, kuchambua faida na kikomo cha kila mchanganyiko</td></tr><tr><td>E07</td><td>Vizuizi vya u cultivating na njia za kupita</td><td>Kusanidi kwa kina vizuizi ambavyo kila mfumo vinaweza kukutwa nayo katika mazingira tofauti na njia anuwai za kupita kwa vizuizi</td><td>Hati 14, Hati 19</td><td>Inaweza kusanidi aina tofauti za vizuizi kama vile &quot;msiba wa shetani wa akili&quot;, &quot;kizuizi cha sheria&quot;, &quot;kizuizi cha asili&quot;, na njia za kupita zinazolingana, kuongeza kiwango cha mchakato wa u cultivating</td></tr><tr><td>E08</td><td>Mwili maalum na uingiliano wa mfumo</td><td>Kusanidi mazingira tofauti ya mwili maalum (kama vile mwili wa asili wa dao, mwili wa ukaribu wa kiini, mwili wa hisia za akili, n.k.) na uhusiano wa uingiliano wao na mifumo tofauti ya u cultivating</td><td>Hati 12, Hati 51</td><td>Inaweza kubuni &quot;matra ya uingiliano wa mwili-mfumo&quot; ili kusaidia wabunifu kuhukumia haraka mifumo ipi inafaa kwa mazingira fulani ya mwili</td></tr><tr><td>E09</td><td>Uainishaji wa kina wa rasilimali za u cultivating</td><td>Kuangazia na kusanidi kwa kina rasilimali anuwai zinazohitajika kwa u cultivating (mali za asili, kristali za nguvu, vipande vya sheria, n.k.)</td><td>Hati 18, Hati 65</td><td>Inaweza kusanidi kiwango, mahali pa uzalishaji, njia ya kukusanya, njia ya kuhifadhi, marufuku ya matumizi ya rasilimali, n.k., kujenga mfumo kamili wa mazingira ya rasilimali za u cultivating</td></tr></tbody></table><h2 id="_4-mwelekeo-wa-upanuzi-wa-mfumo-wa-kijamii" tabindex="-1">4. Mwelekeo wa Upanuzi wa Mfumo wa Kijamii <a class="header-anchor" href="#_4-mwelekeo-wa-upanuzi-wa-mfumo-wa-kijamii" aria-label="Permalink to &quot;4. Mwelekeo wa Upanuzi wa Mfumo wa Kijamii&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Mwelekeo wa Upanuzi</th><th>Thamani ya Upanuzi</th><th>Mipangilio Inayohusiana</th><th>Pendekezo la Ubunifu</th></tr></thead><tbody><tr><td>E10</td><td>Mifumo ya kijamii mahususi ya aina tano</td><td>Kupanua kwa kina mifumo ya kijamii mahususi, mifumo ya uchumi, na tabia za kitamaduni za kila aina katika aina tano za uainishaji wa ustaarabu wa usawa</td><td>Hati 30-35</td><td>Kila aina inaweza kusanidi umbo la jiji la kawaida, muundo wa familia, mfumo wa elimu, sherehe za sikukuu, n.k., kufanya aina tano kuwa zenye tabia za kila moja</td></tr><tr><td>E11</td><td>Mipango na ujenzi wa miji ya usawa</td><td>Kusanidi dhana ya mipango, mtindo wa ujenzi, miundombinu ya msingi, na uainishaji wa kazi ya miji katika ustaarabu wa usawa</td><td>Hati 39, Hati 60</td><td>Inaweza kubuni aina tofauti za umbo la miji kama vile &quot;miji ya usawa ya wima&quot;, &quot;miji ya viota vya mazingira&quot;, &quot;miji ya kunama kwa nafasi&quot;</td></tr><tr><td>E12</td><td>Uendeshaji wa kina wa mfumo wa elimu</td><td>Kusanidi kwa kina mchakato kamili wa uendeshaji wa mfumo wa elimu ya usawa, kutoka elimu ya awali hadi elimu ya juu na elimu ya u cultivating</td><td>Hati 37, Hati 43</td><td>Inaweza kusanidi mfumo wa masomo, njia za tathmini, mfumo wa walimu, mipango ya elimu ya kati ya makabila, n.k.</td></tr><tr><td>E13</td><td>Uendeshaji wa kina wa mfumo wa matibabu</td><td>Kusanidi kwa kina mchakato wa uendeshaji wa mfumo wa matibabu ya usawa, ikiwa ni pamoja na mchanganyiko wa matibabu ya kawaida na matibabu ya u cultivating</td><td>Hati 38, Hati 44</td><td>Inaweza kusanidi mfumo wa hospitali, mchakato wa malipo ya bima ya afya, kanuni maalum za matibabu ya u cultivating, mipango ya matibabu ya kati ya makabila, n.k.</td></tr><tr><td>E14</td><td>Usalama wa kijamii na mfumo wa fursa</td><td>Kusanidi kwa kina mfumo wa usalama wa kijamii wa ustaarabu wa usawa, ikiwa ni pamoja na uzee, ukosefu wa ajira, msaada, n.k.</td><td>Hati 32, Hati 08</td><td>Inaweza kusanidi masharti ya kuomba fursa, viwango vya mgawanyo, vyanzo vya fedha, mifumo ya ufuatiliaji, n.k.</td></tr></tbody></table><h2 id="_5-mwelekeo-wa-upanuzi-wa-kisheria-na-utawala" tabindex="-1">5. Mwelekeo wa Upanuzi wa Kisheria na Utawala <a class="header-anchor" href="#_5-mwelekeo-wa-upanuzi-wa-kisheria-na-utawala" aria-label="Permalink to &quot;5. Mwelekeo wa Upanuzi wa Kisheria na Utawala&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Mwelekeo wa Upanuzi</th><th>Thamani ya Upanuzi</th><th>Mipangilio Inayohusiana</th><th>Pendekezo la Ubunifu</th></tr></thead><tbody><tr><td>E15</td><td>Masuala ya kisheria ya kawaida</td><td>Kuandika masuala ya kawaida yaliyohukumiwa na Mahakama ya Usawa, kuonyesha matumizi ya kisheria katika utendaji</td><td>Hati 40-49, Hati 92</td><td>Inaweza kuandika masuala ya uwakilishi kama vile &quot;kesi ya uk垄断 wa rasilimali za u cultivating&quot;, &quot;kesi ya fidia ya uchafuliaji kati ya usawa&quot;, &quot;kesi ya haki za mwili wa uingizwaji wa giza&quot;</td></tr><tr><td>E16</td><td>Mfumo wa utawala wa mahali</td><td>Kusanidi kwa kina mfumo wa utawala wa mahali na mgawanyo wa mamlaka wa kila eneo la nyota, kila usawa katika mfumo wa katiba</td><td>Hati 40, Hati 49</td><td>Inaweza kusanidi mifumo ya utawala wa vitengo vya utawala tofauti, uhusiano na serikali kuu, mchakato wa kuunda kanuni za utawala, n.k.</td></tr><tr><td>E17</td><td>Mfumo wa uchaguzi na demokrasia</td><td>Kusanidi kwa kina mfumo wa uchaguzi wa wawakilishi wa Baraza la Nanga na mchakato wa uamuzi wa kidemokrasia</td><td>Hati 32, Hati 49</td><td>Inaweza kusanidi uainishaji wa eneo la uchaguzi, sifa ya mgombea, mchakato wa uchaguzi, njia ya kupiga kura, mfumo wa muda wa madarakani, n.k.</td></tr><tr><td>E18</td><td>Mchakato wa utekelezaji wa sheria</td><td>Kusanidi kwa kina mchakato wa utekelezaji wa sheria, ikiwa ni pamoja na mashirika ya utekelezaji, mchakato wa utekelezaji, hatua za kulazimisha</td><td>Hati 48, Hati 49</td><td>Inaweza kusanidi muundo wa mashirika ya utekelezaji, mamlaka ya utekelezaji, mchakato wa utekelezaji, mifumo ya ufuatiliaji, n.k.</td></tr></tbody></table><h2 id="_6-mwelekeo-wa-upanuzi-wa-maisha-na-makabila" tabindex="-1">6. Mwelekeo wa Upanuzi wa Maisha na Makabila <a class="header-anchor" href="#_6-mwelekeo-wa-upanuzi-wa-maisha-na-makabila" aria-label="Permalink to &quot;6. Mwelekeo wa Upanuzi wa Maisha na Makabila&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Mwelekeo wa Upanuzi</th><th>Thamani ya Upanuzi</th><th>Mipangilio Inayohusiana</th><th>Pendekezo la Ubunifu</th></tr></thead><tbody><tr><td>E19</td><td>Mipangilio ya kina ya kabila moja</td><td>Kupanua kwa kina kabila moja kutoka katika Orodha ya Makabila Yote, ikiwa ni pamoja na tabia za kibaolojia, muundo wa kijamii, desturi za kitamaduni, mageuzi ya kihistoria</td><td>Hati 50-52, Hati 94</td><td>Inapendekezwa kipaumbele kupanua makabila yenye tabia kama vile kabila la jaki, kabila la jini, kabila la mitambo, kabila la viumbe vya akili; kila kabila linaweza kujumuisha lugha, dini, sanaa, desturi, n.k.</td></tr><tr><td>E20</td><td>Masuala mahususi ya maisha ya ajabu</td><td>Kusanidi watu binafsi au vikundi vya maisha ya ajabu mahususi, kuonyesha matumizi ya vitendo vya aina tatu</td><td>Hati 53-54</td><td>Inaweza kusanidi masuala ya maisha ya ajabu kama vile &quot;watu wanaotiririka katika utupu&quot;, &quot;maisha ya vipande vya wakati&quot;, &quot;viumbe vya vimelea vya sheria&quot;</td></tr><tr><td>E21</td><td>Aina mahususi za nguvu ya ajabu</td><td>Kusanidi kwa kina tabia, vyanzo, matumizi, na njia za udhibiti wa nguvu anuwai ya ajabu</td><td>Hati 55-56</td><td>Inaweza kusanidi aina za nguvu ya ajabu kama vile &quot;nguvu ya sababu&quot;, &quot;nguvu ya akili&quot;, &quot;nguvu ya sauti ya wakati&quot;</td></tr><tr><td>E22</td><td>Masuala mahususi ya mwili wa uingizwaji wa giza</td><td>Kusanidi hadithi za watu binafsi mahususi za mwili wa uingizwaji wa giza, kuonyesha matumizi ya maadili ya roho mbili na vitendo vya matawi manne</td><td>Hati 57-59</td><td>Inaweza kuandika hadithi za masuala za aina tofauti za mwili wa uingizwaji wa giza, kuchunguza changamoto za maadili za kuishi pamoja kwa roho mbili</td></tr><tr><td>E23</td><td>Uzao wa mchanganyiko kati ya makabila</td><td>Kusanidi tabia na utamaduni wa makabila ya mchanganyiko yanayotokana na ndoa kati ya makabila tofauti</td><td>Hati 52, Hati 77</td><td>Inaweza kusanidi makabila ya mchanganyiko kama vile &quot;nusu jini&quot;, &quot;mtu jaki&quot;, &quot;mtu wa kibaolojia wa mitambo&quot;, kuchunguza utambulisho na mchanganyiko wa utamaduni wao</td></tr></tbody></table><h2 id="_7-mwelekeo-wa-upanuzi-wa-teknolojia-na-nguvu" tabindex="-1">7. Mwelekeo wa Upanuzi wa Teknolojia na Nguvu <a class="header-anchor" href="#_7-mwelekeo-wa-upanuzi-wa-teknolojia-na-nguvu" aria-label="Permalink to &quot;7. Mwelekeo wa Upanuzi wa Teknolojia na Nguvu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Mwelekeo wa Upanuzi</th><th>Thamani ya Upanuzi</th><th>Mipangilio Inayohusiana</th><th>Pendekezo la Ubunifu</th></tr></thead><tbody><tr><td>E24</td><td>Kanuni za kina za teknolojia moja</td><td>Kuchambua kwa kina kanuni za teknolojia moja muhimu (kama vile kioo cha nakala, nafasi iliyotengwa, uhandisi wa tunda la Bei Zeng)</td><td>Hati 60-69, Hati 63-64</td><td>Inaweza kusanidi historia ya maendeleo ya teknolojia, vipengele vya msingi, mchakato wa kazi, kikomo cha teknolojia, mwelekeo wa sasisho, n.k.</td></tr><tr><td>E25</td><td>Uainishaji wa kina wa vyombo vya u cultivating</td><td>Kusanidi uainishaji, kazi, kiwango, na njia za matumizi ya vyombo anuwai vya msaada wa u cultivating</td><td>Hati 61, Hati 67</td><td>Inaweza kusanidi aina za vyombo kama vile &quot;chumba cha u cultivating&quot;, &quot;kibaini cha sheria&quot;, &quot;kibadilishaji cha nguvu&quot;, &quot;kizunguzaji cha akili&quot;</td></tr><tr><td>E26</td><td>Mipangilio ya kina ya vifaa vya nanga</td><td>Kusanidi kwa kina muundo, kazi, ujenzi na utunzaji wa misingi ya vifaa vya nanga</td><td>Hati 20, Hati 67</td><td>Inaweza kusanidi vipengele vya msingi vya nanga ya bandia, ugavi wa nguvu, mzunguko wa utunzaji, usimamizi wa makosa, n.k.</td></tr><tr><td>E27</td><td>Teknolojia ya mawasiliano kati ya usawa</td><td>Kusanidi kwa kina kanuni za teknolojia, aina za vifaa, itifaki za mawasiliano na mifumo ya usalama ya mawasiliano kati ya usawa</td><td>Hati 66, Hati 81</td><td>Inaweza kusanidi njia tofauti za mawasiliano kama vile &quot;mawasiliano ya wimbi la nanga&quot;, &quot;mawasiliano ya kunama kwa nafasi&quot;, &quot;mawasiliano ya mtiririko wa akili&quot;</td></tr></tbody></table><h2 id="_8-mwelekeo-wa-upanuzi-wa-kihistoria-na-matukio" tabindex="-1">8. Mwelekeo wa Upanuzi wa Kihistoria na Matukio <a class="header-anchor" href="#_8-mwelekeo-wa-upanuzi-wa-kihistoria-na-matukio" aria-label="Permalink to &quot;8. Mwelekeo wa Upanuzi wa Kihistoria na Matukio&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Mwelekeo wa Upanuzi</th><th>Thamani ya Upanuzi</th><th>Mipangilio Inayohusiana</th><th>Pendekezo la Ubunifu</th></tr></thead><tbody><tr><td>E28</td><td>Maelezo ya kina ya matukio muhimu ya kihistoria</td><td>Maelezo ya kihistoria ya kina ya tukio moja muhimu katika kronikali</td><td>Hati 70-79, Hati 93</td><td>Inaweza kuelezea kwa kina mchakato kamili wa matukio kama vile &quot;tukio la kufunguliwa kwa mifumo mia tatu&quot;, &quot;utekelezaji wa mkakati wa uanzishaji wa 20%&quot;, &quot;alama ya kwanza ya kuongeza kiwango&quot;</td></tr><tr><td>E29</td><td>Wasifu wa watu wa kihistoria</td><td>Kuandika wasifu wa kina kwa watu muhimu, kuimarisha kina ya kibinadamu ya kihistoria</td><td>Hati 95</td><td>Inaweza kuandika wasifu kwa watu muhimu kama vile &quot;Xuan Hengzi&quot;, &quot;Gongshengzi&quot;, &quot;Lixiangong&quot;, &quot;Sanbaishi&quot;</td></tr><tr><td>E30</td><td>Uchambuzi wa mfano wa mabadiliko ya kihistoria</td><td>Kuchambua ikiwa tukio moja la kihistoria linaenda kwa mwelekeo tofauti, maendeleo ya ustaarabu wa usawa yatakuwa tofauti vipi</td><td>Hati 70-79</td><td>Inaweza kufanya uchambuzi wa mfano kama vile &quot;kama katiba ya usawa isingepitishwa&quot;, &quot;kama mkakati wa uanzishaji wa 20% ungeshindwa&quot;, kuonyesha bahati ya kihistoria</td></tr><tr><td>E31</td><td>Rekodi za kina za ugunduzi wa kale</td><td>Kusanidi ugunduzi wa kina na matokeo ya utafiti wa uchunguzi wa kale wa usawa mmoja</td><td>Hati 84-87</td><td>Inaweza kusanidi kama vile &quot;ugunduzi wa kale wa ustaarabu uliopotea&quot;, &quot;matokeo ya uchunguzi wa kale wa kurudia nyuma kwa wakati wa nodi muhimu ya kihistoria&quot;</td></tr></tbody></table><h2 id="_9-mwelekeo-wa-upanuzi-wa-kati-ya-usawa-na-wakati" tabindex="-1">9. Mwelekeo wa Upanuzi wa Kati ya Usawa na Wakati <a class="header-anchor" href="#_9-mwelekeo-wa-upanuzi-wa-kati-ya-usawa-na-wakati" aria-label="Permalink to &quot;9. Mwelekeo wa Upanuzi wa Kati ya Usawa na Wakati&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Mwelekeo wa Upanuzi</th><th>Thamani ya Upanuzi</th><th>Mipangilio Inayohusiana</th><th>Pendekezo la Ubunifu</th></tr></thead><tbody><tr><td>E32</td><td>Mipangilio ya kina ya usawa mmoja mahususi</td><td>Kusanidi parametri za sheria, umbo la ustaarabu, mazingira ya kijiografia na historia ya usawa mmoja mahususi</td><td>Hati 80, Hati 81</td><td>Inaweza kusanidi aina tofauti za usawa mahususi kama vile &quot;usawa wa uchawi wa juu&quot;, &quot;usawa wa teknolojia&quot;, &quot;usawa wa pori&quot;, &quot;usawa wa akili&quot;</td></tr><tr><td>E33</td><td>Masuala ya ubalozi kati ya usawa</td><td>Kusanidi masuala mahususi ya ustaarabu wa usawa na ustaarabu wa usawa mwingine kuanzisha uhusiano wa ubalozi</td><td>Hati 81, Hati 88</td><td>Inaweza kusanidi matukio mahususi ya ubalozi kama vile mawasiliano ya kwanza, mazungumzo ya ubalozi, ubadilishanaji wa kitamaduni, mikataba ya biashara</td></tr><tr><td>E34</td><td>Masuala mahususi ya kurudia nyuma kwa wakati</td><td>Kusanidi mchakato mahususi, ugunduzi na athari za operesheni moja ya kurudia nyuma kwa wakati</td><td>Hati 82-83, Hati 89</td><td>Inaweza kusanidi masuala kama vile &quot;kutatua kwa kurudia nyuma kwa siri ya kihistoria&quot;, &quot;kurejesha kwa kurudia nyuma kwa ustaarabu uliopotea&quot;</td></tr><tr><td>E35</td><td>Rekodi za kina za tukio la paradoksi ya wakati</td><td>Kusanidi mchakato kamili wa kutokea, majibu ya dharura na urekebishaji wa sababu wa tukio la paradoksi ya wakati</td><td>Hati 89</td><td>Inaweza kuandika rekodi kamili ya usimamizi wa tukio la paradoksi la ndogo, kuonyesha utendaji wa vitendo wa kuzuia na kudhibiti</td></tr><tr><td>E36</td><td>Migogoro na kutatua kati ya usawa</td><td>Kusanidi migogoro kati ya ustaarabu wa usawa na ustaarabu wa usawa mwingine na mchakato wa kutatua amani wao</td><td>Hati 81, Hati 88</td><td>Inaweza kusanidi aina tofauti za masuala ya migogoro kati ya usawa kama vile mizozo ya rasilimali, migogoro ya kitamaduni, mizozo ya mipaka</td></tr></tbody></table><h2 id="_10-kanuni-za-ubunifu-wa-mipangilio-ya-upanuzi" tabindex="-1">10. Kanuni za Ubunifu wa Mipangilio ya Upanuzi <a class="header-anchor" href="#_10-kanuni-za-ubunifu-wa-mipangilio-ya-upanuzi" aria-label="Permalink to &quot;10. Kanuni za Ubunifu wa Mipangilio ya Upanuzi&quot;">​</a></h2><p>Wakati wa kufanya ubunifu wa mipangilio ya upanuzi, inapaswa kufuata kanuni zifuatazo:</p><ol><li><strong>Utendekanaji kipaumbele</strong>: Mipangilio yote ya upanuzi lazima idumishe utendekanaji wa kimantiki na mipangilio iliyopo, na ipite katika ukaguzi wa jedwali la kujikagua utofauti wa mipangilio.</li><li><strong>Kulingana na ukweli</strong>: Mipangilio ya upanuzi inapaswa kuzingatia sheria za kisayansi kwa tafakari zenye busara, kuepuka ubunifu safi na kuanguka kwa mipangilio.</li><li><strong>Msimamo wa usawa</strong>: Mipangilio ya upanuzi lazima daima idumishe msimamo wa msingi wa kupinga ubaozi na kushauri usawa, haifai kutetea tabia za ubaozi.</li><li><strong>Ufunguzi</strong>: Mipangilio ya upanuzi inapaswa kudumisha kiwango fulani cha ufunguzi, kuacha nafasi kwa upanuzi zaidi katika siku zijazo.</li><li><strong>Uitilaji</strong>: Mipangilio ya upanuzi inapaswa kuwa na thamani ya ubunifu wa vitendo, ikiwa na uwezo wa kutoa nyenzo zenye manufaa kwa ubunifu wa hadithi, ubunifu wa michezo, na majadiliano ya kinadharia.</li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Orodha ya Mapendekezo ya Mipangilio ya Upanuzi ni &quot;mlango uliofunguliwa&quot; wa mfumo wa mipangilio wa Ustaarabu wa Usawa wa Nanga. Inaonyesha kwamba mfumo huu wa mipangilio sio bidhaa iliyofungwa, iliyokamilika, bali ni mfumo hai unaokua kwa kushindania na kujengwa kila wakati. Mwelekeo thelathini na sita wa upanuzi ni tu hatua ya kwanza; ubunifu wa kweli wa mipangilio unatoka katika kufikiria na shauku ya kila mshiriki. Kwa madhara kanuni za msingi za utendekanaji wa mipangilio zinakifuata, kila upanuzi wenye thamani utakuwa sehemu isiyoweza kuthibitishwa katika hadithi kubwa ya Ustaarabu wa Usawa wa Nanga.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>97-Jedwali la Kujikagua Utofauti wa Mipangilio</li><li>99-Toleo na Maelezo ya Utunzaji wa Hati</li><li>96-Maswali ya Kawaida FAQ</li></ul>',27)])])}const z=i(o,[["render",k]]);export{s as __pageData,z as default};
